# ! [doc = " # The Rust Standard Library"] # ! [doc = ""] # ! [doc = " The Rust Standard Library is the foundation of portable Rust software, a"] # ! [doc = " set of minimal and battle-tested shared abstractions for the [broader Rust"] # ! [doc = " ecosystem][crates.io]. It offers core types, like [`Vec<T>`] and"] # ! [doc = " [`Option<T>`], library-defined [operations on language"] # ! [doc = " primitives](#primitives), [standard macros](#macros), [I/O] and"] # ! [doc = " [multithreading], among [many other things][other]."] # ! [doc = ""] # ! [doc = " `std` is available to all Rust crates by default. Therefore, the"] # ! [doc = " standard library can be accessed in [`use`] statements through the path"] # ! [doc = " `std`, as in [`use std::env`]."] # ! [doc = ""] # ! [doc = " # How to read this documentation"] # ! [doc = ""] # ! [doc = " If you already know the name of what you are looking for, the fastest way to"] # ! [doc = " find it is to use the <a href=\"#\" onclick=\"window.searchState.focus();\">search"] # ! [doc = " button</a> at the top of the page."] # ! [doc = ""] # ! [doc = " Otherwise, you may want to jump to one of these useful sections:"] # ! [doc = ""] # ! [doc = " * [`std::*` modules](#modules)"] # ! [doc = " * [Primitive types](#primitives)"] # ! [doc = " * [Standard macros](#macros)"] # ! [doc = " * [The Rust Prelude]"] # ! [doc = ""] # ! [doc = " If this is your first time, the documentation for the standard library is"] # ! [doc = " written to be casually perused. Clicking on interesting things should"] # ! [doc = " generally lead you to interesting places. Still, there are important bits"] # ! [doc = " you don't want to miss, so read on for a tour of the standard library and"] # ! [doc = " its documentation!"] # ! [doc = ""] # ! [doc = " Once you are familiar with the contents of the standard library you may"] # ! [doc = " begin to find the verbosity of the prose distracting. At this stage in your"] # ! [doc = " development you may want to press the"] # ! [doc = " \"<svg style=\"width:0.75rem;height:0.75rem\" viewBox=\"0 0 12 12\" stroke=\"currentColor\" fill=\"none\"><path d=\"M2,2l4,4l4,-4M2,6l4,4l4,-4\"/></svg>&nbsp;Summary\""] # ! [doc = " button near the top of the page to collapse it into a more skimmable view."] # ! [doc = ""] # ! [doc = " While you are looking at the top of the page, also notice the"] # ! [doc = " \"Source\" link. Rust's API documentation comes with the source"] # ! [doc = " code and you are encouraged to read it. The standard library source is"] # ! [doc = " generally high quality and a peek behind the curtains is"] # ! [doc = " often enlightening."] # ! [doc = ""] # ! [doc = " # What is in the standard library documentation?"] # ! [doc = ""] # ! [doc = " First of all, The Rust Standard Library is divided into a number of focused"] # ! [doc = " modules, [all listed further down this page](#modules). These modules are"] # ! [doc = " the bedrock upon which all of Rust is forged, and they have mighty names"] # ! [doc = " like [`std::slice`] and [`std::cmp`]. Modules' documentation typically"] # ! [doc = " includes an overview of the module along with examples, and are a smart"] # ! [doc = " place to start familiarizing yourself with the library."] # ! [doc = ""] # ! [doc = " Second, implicit methods on [primitive types] are documented here. This can"] # ! [doc = " be a source of confusion for two reasons:"] # ! [doc = ""] # ! [doc = " 1. While primitives are implemented by the compiler, the standard library"] # ! [doc = "    implements methods directly on the primitive types (and it is the only"] # ! [doc = "    library that does so), which are [documented in the section on"] # ! [doc = "    primitives](#primitives)."] # ! [doc = " 2. The standard library exports many modules *with the same name as"] # ! [doc = "    primitive types*. These define additional items related to the primitive"] # ! [doc = "    type, but not the all-important methods."] # ! [doc = ""] # ! [doc = " So for example there is a [page for the primitive type"] # ! [doc = " `i32`](primitive::i32) that lists all the methods that can be called on"] # ! [doc = " 32-bit integers (very useful), and there is a [page for the module"] # ! [doc = " `std::i32`] that documents the constant values [`MIN`] and [`MAX`] (rarely"] # ! [doc = " useful)."] # ! [doc = ""] # ! [doc = " Note the documentation for the primitives [`str`] and [`[T]`][prim@slice] (also"] # ! [doc = " called 'slice'). Many method calls on [`String`] and [`Vec<T>`] are actually"] # ! [doc = " calls to methods on [`str`] and [`[T]`][prim@slice] respectively, via [deref"] # ! [doc = " coercions][deref-coercions]."] # ! [doc = ""] # ! [doc = " Third, the standard library defines [The Rust Prelude], a small collection"] # ! [doc = " of items - mostly traits - that are imported into every module of every"] # ! [doc = " crate. The traits in the prelude are pervasive, making the prelude"] # ! [doc = " documentation a good entry point to learning about the library."] # ! [doc = ""] # ! [doc = " And finally, the standard library exports a number of standard macros, and"] # ! [doc = " [lists them on this page](#macros) (technically, not all of the standard"] # ! [doc = " macros are defined by the standard library - some are defined by the"] # ! [doc = " compiler - but they are documented here the same). Like the prelude, the"] # ! [doc = " standard macros are imported by default into all crates."] # ! [doc = ""] # ! [doc = " # Contributing changes to the documentation"] # ! [doc = ""] # ! [doc = " Check out the Rust contribution guidelines [here]("] # ! [doc = " https://rustc-dev-guide.rust-lang.org/contributing.html#writing-documentation)."] # ! [doc = " The source for this documentation can be found on"] # ! [doc = " [GitHub](https://github.com/rust-lang/rust) in the 'library/std/' directory."] # ! [doc = " To contribute changes, make sure you read the guidelines first, then submit"] # ! [doc = " pull-requests for your suggested changes."] # ! [doc = ""] # ! [doc = " Contributions are appreciated! If you see a part of the docs that can be"] # ! [doc = " improved, submit a PR, or chat with us first on [Discord][rust-discord]"] # ! [doc = " #docs."] # ! [doc = ""] # ! [doc = " # A Tour of The Rust Standard Library"] # ! [doc = ""] # ! [doc = " The rest of this crate documentation is dedicated to pointing out notable"] # ! [doc = " features of The Rust Standard Library."] # ! [doc = ""] # ! [doc = " ## Containers and collections"] # ! [doc = ""] # ! [doc = " The [`option`] and [`result`] modules define optional and error-handling"] # ! [doc = " types, [`Option<T>`] and [`Result<T, E>`]. The [`iter`] module defines"] # ! [doc = " Rust's iterator trait, [`Iterator`], which works with the [`for`] loop to"] # ! [doc = " access collections."] # ! [doc = ""] # ! [doc = " The standard library exposes three common ways to deal with contiguous"] # ! [doc = " regions of memory:"] # ! [doc = ""] # ! [doc = " * [`Vec<T>`] - A heap-allocated *vector* that is resizable at runtime."] # ! [doc = " * [`[T; N]`][prim@array] - An inline *array* with a fixed size at compile time."] # ! [doc = " * [`[T]`][prim@slice] - A dynamically sized *slice* into any other kind of contiguous"] # ! [doc = "   storage, whether heap-allocated or not."] # ! [doc = ""] # ! [doc = " Slices can only be handled through some kind of *pointer*, and as such come"] # ! [doc = " in many flavors such as:"] # ! [doc = ""] # ! [doc = " * `&[T]` - *shared slice*"] # ! [doc = " * `&mut [T]` - *mutable slice*"] # ! [doc = " * [`Box<[T]>`][owned slice] - *owned slice*"] # ! [doc = ""] # ! [doc = " [`str`], a UTF-8 string slice, is a primitive type, and the standard library"] # ! [doc = " defines many methods for it. Rust [`str`]s are typically accessed as"] # ! [doc = " immutable references: `&str`. Use the owned [`String`] for building and"] # ! [doc = " mutating strings."] # ! [doc = ""] # ! [doc = " For converting to strings use the [`format!`] macro, and for converting from"] # ! [doc = " strings use the [`FromStr`] trait."] # ! [doc = ""] # ! [doc = " Data may be shared by placing it in a reference-counted box or the [`Rc`]"] # ! [doc = " type, and if further contained in a [`Cell`] or [`RefCell`], may be mutated"] # ! [doc = " as well as shared. Likewise, in a concurrent setting it is common to pair an"] # ! [doc = " atomically-reference-counted box, [`Arc`], with a [`Mutex`] to get the same"] # ! [doc = " effect."] # ! [doc = ""] # ! [doc = " The [`collections`] module defines maps, sets, linked lists and other"] # ! [doc = " typical collection types, including the common [`HashMap<K, V>`]."] # ! [doc = ""] # ! [doc = " ## Platform abstractions and I/O"] # ! [doc = ""] # ! [doc = " Besides basic data types, the standard library is largely concerned with"] # ! [doc = " abstracting over differences in common platforms, most notably Windows and"] # ! [doc = " Unix derivatives."] # ! [doc = ""] # ! [doc = " Common types of I/O, including [files], [TCP], and [UDP], are defined in"] # ! [doc = " the [`io`], [`fs`], and [`net`] modules."] # ! [doc = ""] # ! [doc = " The [`thread`] module contains Rust's threading abstractions. [`sync`]"] # ! [doc = " contains further primitive shared memory types, including [`atomic`], [`mpmc`] and"] # ! [doc = " [`mpsc`], which contains the channel types for message passing."] # ! [doc = ""] # ! [doc = " # Use before and after `main()`"] # ! [doc = ""] # ! [doc = " Many parts of the standard library are expected to work before and after `main()`;"] # ! [doc = " but this is not guaranteed or ensured by tests. It is recommended that you write your own tests"] # ! [doc = " and run them on each platform you wish to support."] # ! [doc = " This means that use of `std` before/after main, especially of features that interact with the"] # ! [doc = " OS or global state, is exempted from stability and portability guarantees and instead only"] # ! [doc = " provided on a best-effort basis. Nevertheless bug reports are appreciated."] # ! [doc = ""] # ! [doc = " On the other hand `core` and `alloc` are most likely to work in such environments with"] # ! [doc = " the caveat that any hookable behavior such as panics, oom handling or allocators will also"] # ! [doc = " depend on the compatibility of the hooks."] # ! [doc = ""] # ! [doc = " Some features may also behave differently outside main, e.g. stdio could become unbuffered,"] # ! [doc = " some panics might turn into aborts, backtraces might not get symbolicated or similar."] # ! [doc = ""] # ! [doc = " Non-exhaustive list of known limitations:"] # ! [doc = ""] # ! [doc = " - after-main use of thread-locals, which also affects additional features:"] # ! [doc = "   - [`thread::current()`]"] # ! [doc = " - under UNIX, before main, file descriptors 0, 1, and 2 may be unchanged"] # ! [doc = "   (they are guaranteed to be open during main,"] # ! [doc = "    and are opened to /dev/null O_RDWR if they weren't open on program start)"] # ! [doc = ""] # ! [doc = ""] # ! [doc = " [I/O]: io"] # ! [doc = " [`MIN`]: i32::MIN"] # ! [doc = " [`MAX`]: i32::MAX"] # ! [doc = " [page for the module `std::i32`]: crate::i32"] # ! [doc = " [TCP]: net::TcpStream"] # ! [doc = " [The Rust Prelude]: prelude"] # ! [doc = " [UDP]: net::UdpSocket"] # ! [doc = " [`Arc`]: sync::Arc"] # ! [doc = " [owned slice]: boxed"] # ! [doc = " [`Cell`]: cell::Cell"] # ! [doc = " [`FromStr`]: str::FromStr"] # ! [doc = " [`HashMap<K, V>`]: collections::HashMap"] # ! [doc = " [`Mutex`]: sync::Mutex"] # ! [doc = " [`Option<T>`]: option::Option"] # ! [doc = " [`Rc`]: rc::Rc"] # ! [doc = " [`RefCell`]: cell::RefCell"] # ! [doc = " [`Result<T, E>`]: result::Result"] # ! [doc = " [`Vec<T>`]: vec::Vec"] # ! [doc = " [`atomic`]: sync::atomic"] # ! [doc = " [`for`]: ../book/ch03-05-control-flow.html#looping-through-a-collection-with-for"] # ! [doc = " [`str`]: prim@str"] # ! [doc = " [`mpmc`]: sync::mpmc"] # ! [doc = " [`mpsc`]: sync::mpsc"] 